type Node = Parameters<typeof Text>[0]["children"];
type View = "requirements" | "build" | "features" | "data" | "catalogs" | "glossary" | "sources";
type PhaseFilter = "ALL" | Phase;
type Nav = { req: (id: string) => void; entity: (id: string) => void; view: (v: View) => void };

const PHASE_LABEL: Record<Phase, string> = { MVP: "MVP", P2: "Phase 2", P3: "Phase 3" };
const MONO = "ui-monospace, SFMono-Regular, Menlo, monospace";
const LAYER_HUE: Record<string, "blue" | "green" | "purple"> = { "user-interface": "blue", product: "green", platform: "purple" };

const REQ_BY_ID = new Map(G.reqs.map((r) => [r.id, r]));
const MODULES = G.layers.flatMap((l) => l.modules.map((m) => ({ ...m, layer: l.id })));
const MODULE_BY_ID = new Map(MODULES.map((m) => [m.id, m]));
const ENTITY_BY_NAME = new Map(G.entities.map((e) => [e.name, e]));
const ENUM_BY_NAME = new Map(G.enums.map((e) => [e.name, e]));
const DECISION_BY_ID = new Map(G.decisions.map((d) => [d.decision_id, d]));
const SOURCE_BY_KEY = new Map(G.sources.map((s) => [s.source, s]));
const FEATURE_BY_ID = new Map(G.features.map((f) => [f.feature_id, f]));
const CAP_BY_ID = new Map(G.capabilities.map((c) => [c.capability_id, c]));
const FAILED = G.meta.checks.filter((c) => c.problems.length > 0);

function invert(pairs: [string, string][]): Map<string, string[]> {
  const out = new Map<string, string[]>();
  for (const [k, v] of pairs) out.set(k, [...(out.get(k) ?? []), v]);
  return out;
}

const DEPENDENTS = invert(G.reqs.flatMap((r) => r.deps.map((d): [string, string] => [d, r.id])));
const FEATURE_REQS = invert(G.reqs.flatMap((r) => r.features.map((f): [string, string] => [f, r.id])));
const entityOf = (ref: string) => ref.split(".")[0];
const ENTITY_READERS = invert(G.reqs.flatMap((r) => Array.from(new Set(r.dm.reads.map(entityOf))).map((e): [string, string] => [e, r.id])));
const ENTITY_WRITERS = invert(G.reqs.flatMap((r) => Array.from(new Set(r.dm.writes.map(entityOf))).map((e): [string, string] => [e, r.id])));
const DECISION_REQS = invert(G.reqs.flatMap((r) => Array.from(new Set([...r.dec, ...r.rules.flatMap((x) => x.dec)])).map((d): [string, string] => [d, r.id])));
const TRANSITIONS_BY_REQ = invert(G.enums.flatMap((e) => e.transitions.map((t): [string, string] => [t.requirement, `${e.name}: ${t.from ?? "new"} → ${t.to}`])));
const OWNED_BY_REQ = invert([
  ...G.settings.map((s): [string, string] => [s.owner, `Setting ${s.key}`]),
  ...G.notifications.map((n): [string, string] => [n.owner, `Notification ${n.type}`]),
  ...G.uploads.map((u): [string, string] => [u.owner, `Upload type ${u.type}`]),
]);

const WAVE = new Map<string, number>();
function waveOf(id: string, trail: Set<string> = new Set()): number {
  const known = WAVE.get(id);
  if (known !== undefined) return known;
  if (trail.has(id)) return 0;
  trail.add(id);
  const deps = (REQ_BY_ID.get(id)?.deps ?? []).filter((d) => REQ_BY_ID.has(d));
  const w = deps.length ? 1 + Math.max(...deps.map((d) => waveOf(d, trail))) : 1;
  WAVE.set(id, w);
  return w;
}
G.reqs.forEach((r) => waveOf(r.id));

function mix(color: string, pct: number): string {
  return `color-mix(in srgb, ${color} ${pct}%, transparent)`;
}

function matchesPhase(p: Phase, filter: PhaseFilter): boolean {
  return filter === "ALL" || p === filter;
}

/* --------------------------------- Shared --------------------------------- */

function PhaseBadge({ p, prefix }: { p: Phase; prefix?: string }) {
  const theme = useHostTheme();
  const hue = p === "MVP" ? theme.category.green : p === "P2" ? theme.category.yellow : theme.category.gray;
  return (
    <span style={{ display: "inline-block", padding: "1px 8px", borderRadius: 999, fontSize: 11, lineHeight: "18px", whiteSpace: "nowrap", background: mix(hue, 16), border: `1px solid ${mix(hue, 45)}`, color: p === "P3" ? theme.text.secondary : theme.text.primary }}>
      {prefix ? `${prefix} ${PHASE_LABEL[p]}` : PHASE_LABEL[p]}
    </span>
  );
}

function LayerDot({ layer }: { layer: string }) {
  const theme = useHostTheme();
  return <span style={{ display: "inline-block", width: 8, height: 8, borderRadius: 999, background: theme.category[LAYER_HUE[layer] ?? "gray"], flexShrink: 0 }} />;
}

function Clickable({ children, onClick, title, mono }: { children: Node; onClick: () => void; title?: string; mono?: boolean }) {
  const theme = useHostTheme();
  return (
    <span
      role="button"
      title={title}
      onClick={(e: { stopPropagation: () => void }) => {
        e.stopPropagation();
        onClick();
      }}
      style={{ color: theme.text.link, cursor: "pointer", fontFamily: mono ? MONO : undefined, fontSize: mono ? 12 : undefined }}
    >
      {children}
    </span>
  );
}

function ReqLink({ id, nav, withTitle }: { id: string; nav: Nav; withTitle?: boolean }) {
  const r = REQ_BY_ID.get(id);
  return (
    <span style={{ display: "inline-flex", gap: 6, alignItems: "baseline", flexWrap: "wrap", minWidth: 0 }}>
      {r ? <LayerDot layer={r.layer} /> : null}
      <Clickable mono onClick={() => nav.req(id)} title={r?.title}>{id}</Clickable>
      {withTitle && r ? <Text as="span" size="small" tone="secondary">{r.title}</Text> : null}
    </span>
  );
}

function Label({ children }: { children: Node }) {
  return (
    <Text size="small" tone="tertiary" weight="medium" style={{ textTransform: "uppercase", letterSpacing: 0.4 }}>
      {children}
    </Text>
  );
}

function Mono({ children, tone }: { children: Node; tone?: "secondary" | "tertiary" }) {
  const theme = useHostTheme();
  return <span style={{ fontFamily: MONO, fontSize: 12, color: tone === "tertiary" ? theme.text.tertiary : tone === "secondary" ? theme.text.secondary : theme.text.primary }}>{children}</span>;
}

function Citation({ c }: { c: string }) {
  const key = c.split(" ")[0];
  const src = SOURCE_BY_KEY.get(key);
  const rest = c.slice(key.length).trim();
  return (
    <Text as="span" size="small" tone="tertiary">
      {src ? <Link href={src.url}>{key}</Link> : key}
      {rest ? ` ${rest}` : ""}
    </Text>
  );
}

function TabBar({ label, items, active, onSelect }: { label: string; items: { id: string; name: string; count: number; hue?: string }[]; active: string; onSelect: (id: string) => void }) {
  const theme = useHostTheme();
  return (
    <Row gap={10} align="center" wrap>
      <span style={{ minWidth: 64 }}>
        <Label>{label}</Label>
      </span>
      <Row gap={4} wrap>
        {items.map((it) => {
          const on = it.id === active;
          return (
            <span key={it.id} role="button" onClick={() => onSelect(it.id)} style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "4px 10px", borderRadius: 6, cursor: "pointer", fontSize: 12, color: on ? theme.text.primary : theme.text.secondary, background: on ? theme.fill.secondary : "transparent", border: `1px solid ${on ? theme.stroke.secondary : "transparent"}` }}>
              {it.hue ? <span style={{ width: 8, height: 8, borderRadius: 999, background: it.hue }} /> : null}
              {it.name}
              <span style={{ color: theme.text.tertiary }}>{it.count}</span>
            </span>
          );
        })}
      </Row>
    </Row>
  );
}

function PhaseFilterBar({ value, onChange, counts }: { value: PhaseFilter; onChange: (p: PhaseFilter) => void; counts: Record<PhaseFilter, number> }) {
  const opts: PhaseFilter[] = ["ALL", "MVP", "P2", "P3"];
  return (
    <Row gap={6} align="center" wrap>
      <span style={{ minWidth: 64 }}>
        <Label>Phase</Label>
      </span>
      {opts.map((o) => (
        <Pill key={o} active={value === o} onClick={() => onChange(o)}>
          {`${o === "ALL" ? "All" : PHASE_LABEL[o]} · ${counts[o]}`}
        </Pill>
      ))}
    </Row>
  );
}

function phaseCounts<T>(items: T[], phaseOf: (t: T) => Phase): Record<PhaseFilter, number> {
  return {
    ALL: items.length,
    MVP: items.filter((t) => phaseOf(t) === "MVP").length,
    P2: items.filter((t) => phaseOf(t) === "P2").length,
    P3: items.filter((t) => phaseOf(t) === "P3").length,
  };
}

/* ------------------------------ Requirements ------------------------------ */

function RefList({ refs, nav }: { refs: string[]; nav: Nav }) {
  const grouped = new Map<string, string[]>();
  for (const ref of refs) {
    const [entity, field] = ref.split(".");
    grouped.set(entity, [...(grouped.get(entity) ?? []), field]);
  }
  return (
    <Stack gap={2}>
      {Array.from(grouped.entries()).map(([entity, fields]) => (
        <Text key={entity} size="small">
          <Clickable mono onClick={() => nav.entity(entity)}>{entity}</Clickable>
          <Mono tone="tertiary">{` ${fields.join(", ")}`}</Mono>
        </Text>
      ))}
    </Stack>
  );
}

function ReqDetail({ r, nav }: { r: Req; nav: Nav }) {
  const theme = useHostTheme();
  const dependents = DEPENDENTS.get(r.id) ?? [];
  const transitions = TRANSITIONS_BY_REQ.get(r.id) ?? [];
  const owned = OWNED_BY_REQ.get(r.id) ?? [];
  const decisions = Array.from(new Set([...r.dec, ...r.rules.flatMap((x) => x.dec)]));
  return (
    <div style={{ padding: "14px 16px 18px 16px", background: theme.fill.quaternary, borderTop: `1px solid ${theme.stroke.tertiary}` }}>
      <Stack gap={16}>
        <Stack gap={6}>
          <Text>{r.statement}</Text>
          <Row gap={8} wrap align="center">
            <Text size="small" tone="tertiary">Actors:</Text>
            {r.actors.map((a) => <Mono key={a} tone="secondary">{a}</Mono>)}
            {r.src.length ? <Text size="small" tone="tertiary">· Sources:</Text> : null}
            {r.src.map((c) => <Citation key={c} c={c} />)}
          </Row>
        </Stack>

        <Stack gap={8}>
          <Label>Rules (acceptance criteria)</Label>
          {r.rules.map((rule) => (
            <Row key={rule.id} gap={10} align="start">
              <span style={{ fontFamily: MONO, fontSize: 12, color: theme.text.tertiary, minWidth: 28, paddingTop: 2 }}>{rule.id}</span>
              <Stack gap={2} style={{ flex: 1, minWidth: 0 }}>
                <Text>{rule.text}</Text>
                <Row gap={8} wrap>
                  {rule.src.map((c) => <Citation key={c} c={c} />)}
                  {rule.dec.map((d) => (
                    <Clickable key={d} mono onClick={() => nav.view("sources")} title={DECISION_BY_ID.get(d)?.question}>{d}</Clickable>
                  ))}
                </Row>
              </Stack>
            </Row>
          ))}
        </Stack>

        <Grid columns="minmax(0, 1fr) minmax(0, 1fr)" gap={16}>
          <Stack gap={6}>
            <Label>{`Reads · data model ${r.dm.status.replace("_", " ")}`}</Label>
            {r.dm.reads.length ? <RefList refs={r.dm.reads} nav={nav} /> : <Text size="small" tone="tertiary">Nothing</Text>}
            {r.dm.detail ? <Text size="small" tone="secondary">{r.dm.detail}</Text> : null}
          </Stack>
          <Stack gap={6}>
            <Label>Writes</Label>
            {r.dm.writes.length ? <RefList refs={r.dm.writes} nav={nav} /> : <Text size="small" tone="tertiary">Nothing</Text>}
          </Stack>
        </Grid>

        {transitions.length || owned.length ? (
          <Grid columns="minmax(0, 1fr) minmax(0, 1fr)" gap={16}>
            <Stack gap={4}>
              <Label>Status transitions it makes</Label>
              {transitions.length ? transitions.map((t) => <Mono key={t} tone="secondary">{t}</Mono>) : <Text size="small" tone="tertiary">None</Text>}
            </Stack>
            <Stack gap={4}>
              <Label>Catalog entries it owns</Label>
              {owned.length ? owned.map((o) => <Mono key={o} tone="secondary">{o}</Mono>) : <Text size="small" tone="tertiary">None</Text>}
            </Stack>
          </Grid>
        ) : null}

        {r.features.length ? (
          <Stack gap={6}>
            <Label>Sheet features</Label>
            {r.features.map((fid) => (
              <Row key={fid} gap={10} align="start">
                <span style={{ fontFamily: MONO, fontSize: 12, color: theme.text.secondary, minWidth: 56, paddingTop: 2 }}>{fid}</span>
                <Text size="small" style={{ flex: 1, minWidth: 0 }}>{FEATURE_BY_ID.get(fid)?.feature}</Text>
              </Row>
            ))}
          </Stack>
        ) : null}

        {decisions.length ? (
          <Stack gap={6}>
            <Label>Decisions it rests on</Label>
            {decisions.map((d) => {
              const dec = DECISION_BY_ID.get(d);
              return (
                <Row key={d} gap={10} align="start">
                  <span style={{ fontFamily: MONO, fontSize: 12, minWidth: 40, paddingTop: 2, color: dec?.blocking ? theme.category.red : theme.text.secondary }}>{d}</span>
                  <Stack gap={2} style={{ flex: 1, minWidth: 0 }}>
                    <Text size="small">{dec?.question}</Text>
                    <Text size="small" tone="tertiary">{`${dec?.blocking ? "Blocking. " : ""}Assumed: ${dec?.assumption ?? ""}`}</Text>
                  </Stack>
                </Row>
              );
            })}
          </Stack>
        ) : null}

        <Grid columns="minmax(0, 1fr) minmax(0, 1fr)" gap={16}>
          <Stack gap={4}>
            <Row gap={8} align="center">
              <Label>Depends on</Label>
              <Text size="small" tone="tertiary">{`Build wave ${WAVE.get(r.id)}`}</Text>
            </Row>
            {r.deps.length ? r.deps.map((d) => <ReqLink key={d} id={d} nav={nav} withTitle />) : <Text size="small" tone="tertiary">Nothing; it can be built first.</Text>}
          </Stack>
          <Stack gap={4}>
            <Label>Depended on by</Label>
            {dependents.length ? dependents.map((d) => <ReqLink key={d} id={d} nav={nav} withTitle />) : <Text size="small" tone="tertiary">No requirement depends on it.</Text>}
          </Stack>
        </Grid>
        <Text size="small" tone="tertiary">{`Review: ${r.review} · Delivery: ${r.delivery}${r.prs.length ? ` · ${r.prs.join(", ")}` : ""}`}</Text>
      </Stack>
    </div>
  );
}

const REQ_COLUMNS = "210px minmax(0, 1fr) 84px 130px 90px";

function ReqTable({ reqs, expanded, onToggle, nav }: { reqs: Req[]; expanded: string | null; onToggle: (id: string) => void; nav: Nav }) {
  const theme = useHostTheme();
  const head = { fontSize: 11, color: theme.text.tertiary, fontWeight: 500, textTransform: "uppercase" as const, letterSpacing: 0.4 };
  return (
    <div style={{ border: `1px solid ${theme.stroke.tertiary}`, borderRadius: 8, overflow: "hidden" }}>
      <div style={{ display: "grid", gridTemplateColumns: REQ_COLUMNS, gap: 12, padding: "8px 12px", background: theme.fill.tertiary }}>
        <span style={head}>Requirement</span>
        <span style={head}>Title</span>
        <span style={head}>Phase</span>
        <span style={head}>Sheet features</span>
        <span style={head}>Rules</span>
      </div>
      {reqs.map((r) => {
        const open = expanded === r.id;
        return (
          <div key={r.id} id={`req-${r.id}`} style={{ borderTop: `1px solid ${theme.stroke.tertiary}` }}>
            <div role="button" onClick={() => onToggle(r.id)} style={{ display: "grid", gridTemplateColumns: REQ_COLUMNS, gap: 12, padding: "10px 12px", cursor: "pointer", alignItems: "start", background: open ? theme.fill.tertiary : "transparent" }}>
              <span style={{ display: "flex", gap: 6, alignItems: "baseline", whiteSpace: "nowrap" }}>
                <span style={{ color: theme.text.tertiary, fontSize: 10, width: 10 }}>{open ? "▾" : "▸"}</span>
                <span style={{ fontFamily: MONO, fontSize: 12, fontWeight: 600, color: theme.text.primary }}>{r.id}</span>
              </span>
              <Row gap={8} align="center" wrap>
                <Text weight="medium">{r.title}</Text>
                {r.start ? <Text as="span" size="small" tone="tertiary">· Starting flow</Text> : null}
              </Row>
              <span>
                <PhaseBadge p={r.phase} />
              </span>
              <Text size="small" tone={r.features.length ? "secondary" : "quaternary"}>{r.features.length ? r.features.join(", ") : "Supporting"}</Text>
              <Text size="small" tone="tertiary">{String(r.rules.length)}</Text>
            </div>
            {open ? <ReqDetail r={r} nav={nav} /> : null}
          </div>
        );
      })}
    </div>
  );
}

function RequirementsView({ phase, setPhase, layer, setLayer, moduleId, setModuleId, expanded, setExpanded, nav }: { phase: PhaseFilter; setPhase: (p: PhaseFilter) => void; layer: string; setLayer: (l: string) => void; moduleId: string; setModuleId: (m: string) => void; expanded: string | null; setExpanded: (id: string | null) => void; nav: Nav }) {
  const theme = useHostTheme();
  const inPhase = G.reqs.filter((r) => matchesPhase(r.phase, phase));
  const layers = G.layers.map((l) => ({ l, n: inPhase.filter((r) => r.layer === l.id).length })).filter((x) => x.n > 0);
  const activeLayer = layers.some((x) => x.l.id === layer) ? layer : layers[0]?.l.id ?? "product";
  const modules = MODULES.filter((m) => m.layer === activeLayer).map((m) => ({ m, n: inPhase.filter((r) => r.module === m.id).length })).filter((x) => x.n > 0);
  const activeModule = modules.some((x) => x.m.id === moduleId) ? moduleId : modules[0]?.m.id ?? "";
  const mod = MODULE_BY_ID.get(activeModule);
  const rows = inPhase.filter((r) => r.module === activeModule);
  return (
    <Stack gap={12}>
      <PhaseFilterBar value={phase} onChange={setPhase} counts={phaseCounts(G.reqs, (r) => r.phase)} />
      <TabBar label="Layer" items={layers.map(({ l, n }) => ({ id: l.id, name: l.name, count: n, hue: theme.category[LAYER_HUE[l.id] ?? "gray"] }))} active={activeLayer} onSelect={setLayer} />
      <TabBar label="Module" items={modules.map(({ m, n }) => ({ id: m.id, name: m.name, count: n }))} active={activeModule} onSelect={setModuleId} />
      {mod ? (
        <Text size="small" tone="secondary">
          <span style={{ fontFamily: MONO, color: theme.text.tertiary }}>{mod.id}</span>
          {` · ${mod.about}`}
        </Text>
      ) : null}
      <ReqTable reqs={rows} expanded={expanded} onToggle={(id) => setExpanded(expanded === id ? null : id)} nav={nav} />
    </Stack>
  );
}

/* -------------------------------- Build order ------------------------------- */

function BuildView({ nav }: { nav: Nav }) {
  const theme = useHostTheme();
  const mvp = G.reqs.filter((r) => r.phase === "MVP");
  const start = mvp.filter((r) => r.start);
  const waves = Array.from(new Set(mvp.map((r) => WAVE.get(r.id) ?? 0))).sort((a, b) => a - b);
  return (
    <Stack gap={16}>
      <Text tone="secondary">
        The MVP in build order. A requirement sits in the wave after the last of its dependencies, so everything in one wave can be built in parallel. The factory picks only approved requirements whose dependencies are delivered.
      </Text>
      <Stack gap={6}>
        <H3>Starting flow</H3>
        <Text size="small" tone="secondary">The first end-to-end slice from the sheet's Read Me: a Unit posts a Shift, then the Agency creates and assigns a Worker. Every dependency of the slice is in it.</Text>
        <Row gap={14} wrap>
          {start.map((r) => <ReqLink key={r.id} id={r.id} nav={nav} withTitle />)}
        </Row>
      </Stack>
      <Divider />
      {waves.map((w) => {
        const inWave = mvp.filter((r) => WAVE.get(r.id) === w);
        return (
          <Grid key={w} columns="90px minmax(0, 1fr)" gap={12} align="start">
            <Stack gap={2}>
              <Text weight="medium">{`Wave ${w}`}</Text>
              <Text size="small" tone="tertiary">{`${inWave.length} requirements`}</Text>
            </Stack>
            <div style={{ display: "flex", flexWrap: "wrap", gap: "4px 18px", borderLeft: `2px solid ${theme.stroke.tertiary}`, paddingLeft: 12 }}>
              {inWave.map((r) => <ReqLink key={r.id} id={r.id} nav={nav} withTitle />)}
            </div>
          </Grid>
        );
      })}
    </Stack>
  );
}

/* --------------------------------- Features -------------------------------- */

function FeaturesView({ phase, setPhase, nav }: { phase: PhaseFilter; setPhase: (p: PhaseFilter) => void; nav: Nav }) {
  const areas = Array.from(new Set(G.capabilities.map((c) => c.area)));
  const phaseOfFeature = (f: Feature) => CAP_BY_ID.get(f.capability_id)?.phase ?? "P3";
  return (
    <Stack gap={16}>
      <Text tone="secondary">Every feature on the Compass sheet, verbatim, with the requirements that deliver it. Phases are the sheet's suggested priorities (D-32).</Text>
      <PhaseFilterBar value={phase} onChange={setPhase} counts={phaseCounts(G.features, phaseOfFeature)} />
      {areas.map((area) => {
        const caps = G.capabilities.filter((c) => c.area === area && matchesPhase(c.phase, phase));
        if (!caps.length) return null;
        return (
          <Stack key={area} gap={12}>
            <H2>{area}</H2>
            {caps.map((c) => (
              <Stack key={c.capability_id} gap={8}>
                <Row gap={10} align="center" wrap>
                  <Mono tone="tertiary">{c.capability_id}</Mono>
                  <H3>{c.name}</H3>
                  <PhaseBadge p={c.phase} prefix="Suggested" />
                </Row>
                <Text size="small" tone="secondary">{c.description}</Text>
                <Table
                  headers={["Feature", "What it is", "Why", "Requirements"]}
                  rows={G.features.filter((f) => f.capability_id === c.capability_id).map((f) => [
                    <Mono key="id">{f.feature_id}</Mono>,
                    f.feature,
                    <Text key="w" size="small" tone="secondary">{f.why}</Text>,
                    <Stack key="r" gap={2}>
                      {(FEATURE_REQS.get(f.feature_id) ?? []).map((id) => <ReqLink key={id} id={id} nav={nav} />)}
                    </Stack>,
                  ])}
                />
              </Stack>
            ))}
          </Stack>
        );
      })}
    </Stack>
  );
}

/* -------------------------------- Data model ------------------------------- */

function FieldType({ f, nav }: { f: Field; nav: Nav }) {
  const theme = useHostTheme();
  const base = f.type.startsWith("list:") ? f.type.slice(5) : f.type;
  const many = base !== f.type;
  const suffix = `${many ? " list" : ""}${f.nullable ? ", nullable" : ""}`;
  if (base.startsWith("ref:")) {
    const target = base.slice(4);
    return (
      <span style={{ fontFamily: MONO, fontSize: 12 }}>
        <span style={{ color: theme.text.tertiary }}>→ </span>
        <Clickable mono onClick={() => nav.entity(target)}>{target}</Clickable>
        <span style={{ color: theme.text.tertiary }}>{suffix}</span>
      </span>
    );
  }
  if (base.startsWith("enum:")) {
    const name = base.slice(5);
    const en = ENUM_BY_NAME.get(name);
    return (
      <Stack gap={2}>
        <span style={{ fontFamily: MONO, fontSize: 12 }}>{`${name}${suffix}`}</span>
        {en && !en.catalog ? <Text size="small" tone="tertiary">{en.values.map((v) => v.value).join(" · ")}</Text> : null}
        {en?.catalog ? <Text size="small" tone="tertiary">{`Values from the ${en.catalog} catalog`}</Text> : null}
      </Stack>
    );
  }
  return <span style={{ fontFamily: MONO, fontSize: 12, color: theme.text.secondary }}>{`${base}${suffix}`}</span>;
}

function DataModelView({ phase, setPhase, entity, nav }: { phase: PhaseFilter; setPhase: (p: PhaseFilter) => void; entity: string; nav: Nav }) {
  const theme = useHostTheme();
  const visible = G.entities.filter((e) => matchesPhase(e.phase, phase));
  const selected = ENTITY_BY_NAME.get(entity) ?? visible[0];
  const statusEnums = selected
    ? selected.fields.map((f) => (f.type.startsWith("enum:") ? ENUM_BY_NAME.get(f.type.slice(5)) : undefined)).filter((e): e is EnumDef => !!e && e.transitions.length > 0)
    : [];
  return (
    <Stack gap={12}>
      <Text tone="secondary">
        Every entity also has <Mono>id</Mono>, <Mono>created_at</Mono>, and <Mono>updated_at</Mono>. Fields are required unless marked nullable. Money is USD to the cent and hours are whole minutes. Each entity is written only by requirements in its own module.
      </Text>
      <PhaseFilterBar value={phase} onChange={setPhase} counts={phaseCounts(G.entities, (e) => e.phase)} />
      <Grid columns="250px minmax(0, 1fr)" gap={16} align="start">
        <div style={{ border: `1px solid ${theme.stroke.tertiary}`, borderRadius: 8, padding: "8px 0" }}>
          {MODULES.filter((m) => visible.some((e) => e.module === m.id)).map((m) => (
            <div key={m.id} style={{ padding: "6px 12px" }}>
              <Row gap={6} align="center">
                <LayerDot layer={m.layer} />
                <Label>{m.name}</Label>
              </Row>
              <Stack gap={0} style={{ marginTop: 4 }}>
                {visible.filter((e) => e.module === m.id).map((e) => {
                  const on = selected?.name === e.name;
                  return (
                    <div key={e.name} role="button" onClick={() => nav.entity(e.name)} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, padding: "3px 8px", borderRadius: 4, cursor: "pointer", background: on ? theme.fill.secondary : "transparent", borderLeft: `2px solid ${on ? theme.accent.primary : "transparent"}` }}>
                      <span style={{ fontFamily: MONO, fontSize: 12, color: on ? theme.text.primary : theme.text.secondary }}>{e.name}</span>
                      {e.phase !== "MVP" ? <PhaseBadge p={e.phase} /> : null}
                    </div>
                  );
                })}
              </Stack>
            </div>
          ))}
        </div>
        {selected ? (
          <Stack gap={14}>
            <Stack gap={4}>
              <Row gap={10} align="center" wrap>
                <H2 style={{ fontFamily: MONO }}>{selected.name}</H2>
                <PhaseBadge p={selected.phase} />
                <Text size="small" tone="tertiary">{`Owned by ${MODULE_BY_ID.get(selected.module)?.name ?? selected.module}`}</Text>
              </Row>
              <Text tone="secondary">{selected.description}</Text>
            </Stack>
            <Table
              headers={["Field", "Type", "Notes"]}
              rows={selected.fields.map((f) => [<Mono key="n">{f.name}</Mono>, <FieldType key="t" f={f} nav={nav} />, <Text key="no" size="small" tone="secondary">{f.note ?? ""}</Text>])}
            />
            {selected.unique.length || selected.constraints.length ? (
              <Stack gap={4}>
                <Label>Constraints</Label>
                {selected.unique.map((u) => <Text key={u.join()} size="small">{`Unique: ${u.join(" + ")}`}</Text>)}
                {selected.constraints.map((c) => <Text key={c} size="small">{c}</Text>)}
              </Stack>
            ) : null}
            {statusEnums.map((en) => (
              <Stack key={en.name} gap={6}>
                <Label>{`${en.name} lifecycle`}</Label>
                <Table
                  headers={["Value", "Meaning"]}
                  rows={en.values.map((v) => [<Mono key="v">{v.value}</Mono>, <Text key="m" size="small">{v.meaning}</Text>])}
                />
                <Table
                  headers={["From", "To", "Made by"]}
                  rows={en.transitions.map((t, i) => [<Mono key={`f${i}`} tone="secondary">{t.from ?? "(new)"}</Mono>, <Mono key={`t${i}`}>{t.to}</Mono>, <ReqLink key={`r${i}`} id={t.requirement} nav={nav} />])}
                />
              </Stack>
            ))}
            <Grid columns="minmax(0, 1fr) minmax(0, 1fr)" gap={16}>
              <Stack gap={4}>
                <Label>Written by</Label>
                {(ENTITY_WRITERS.get(selected.name) ?? []).map((id) => <ReqLink key={id} id={id} nav={nav} withTitle />)}
              </Stack>
              <Stack gap={4}>
                <Label>Read by</Label>
                {(ENTITY_READERS.get(selected.name) ?? []).map((id) => <ReqLink key={id} id={id} nav={nav} withTitle />)}
              </Stack>
            </Grid>
          </Stack>
        ) : null}
      </Grid>
    </Stack>
  );
}

/* ---------------------------------- Catalogs --------------------------------- */

function CatalogsView({ nav }: { nav: Nav }) {
  const [upload, setUpload] = useCanvasState<string>("upload", G.uploads[0]?.type ?? "");
  const selected = G.uploads.find((u) => u.type === upload) ?? G.uploads[0];
  return (
    <Stack gap={20}>
      <Stack gap={8}>
        <H2>Settings</H2>
        <Text tone="secondary">Program defaults. Settings with scope any can be overridden at any org node; the nearest override up the tree wins.</Text>
        <Table
          headers={["Key", "Default", "Scope", "Meaning", "Owner"]}
          rows={G.settings.map((s) => [<Mono key="k">{s.key}</Mono>, <Mono key="d" tone="secondary">{String(s.default)}</Mono>, s.scope, <Text key="m" size="small">{s.meaning}</Text>, <ReqLink key="o" id={s.owner} nav={nav} />])}
        />
      </Stack>
      <Stack gap={8}>
        <H2>Notifications</H2>
        <Table
          headers={["Type", "Sent when", "To", "Channels", "Owner"]}
          rows={G.notifications.map((n) => [<Mono key="k">{n.type}</Mono>, <Text key="t" size="small">{n.trigger}</Text>, <Text key="r" size="small" tone="secondary">{n.recipients}</Text>, <Mono key="c" tone="secondary">{n.channels.join(", ")}</Mono>, <ReqLink key="o" id={n.owner} nav={nav} />])}
        />
      </Stack>
      <Stack gap={8}>
        <H2>Upload types</H2>
        <Row gap={4} wrap>
          {G.uploads.map((u) => (
            <Pill key={u.type} active={u.type === selected?.type} onClick={() => setUpload(u.type)}>{u.type}</Pill>
          ))}
        </Row>
        {selected ? (
          <Stack gap={8}>
            <Text>{selected.meaning}</Text>
            <Row gap={10} wrap align="center">
              <Text size="small" tone="tertiary">{`Uploaded by ${selected.uploaders.join(", ")} · saved by`}</Text>
              <ReqLink id={selected.owner} nav={nav} withTitle />
            </Row>
            <Table
              headers={["Column", "Required", "Fills", "Notes"]}
              rows={selected.columns.map((c) => [
                <Mono key="c">{c.column}</Mono>,
                <Text key="r" size="small">{c.required}</Text>,
                <Mono key="m" tone="secondary">{c.maps_to}</Mono>,
                <Text key="n" size="small" tone="tertiary">{[c.lookup ? `Lookup: ${c.lookup}` : "", c.saved_by ? `Saved by ${c.saved_by}` : "", c.note ?? ""].filter(Boolean).join(". ")}</Text>,
              ])}
            />
          </Stack>
        ) : null}
      </Stack>
    </Stack>
  );
}

/* ------------------------------ Glossary, sources ------------------------------ */

function GlossaryView() {
  return (
    <Stack gap={12}>
      <Text tone="secondary">The words requirements use. The validator rejects the avoided words in requirement text.</Text>
      <Table
        headers={["Term", "Meaning", "Never write", "Sources say"]}
        rows={G.terms.map((t) => [<Text key="t" weight="medium">{t.term}</Text>, t.definition, <Text key="a" size="small" tone="tertiary">{t.avoid.join(", ")}</Text>, <Text key="s" size="small" tone="tertiary">{(t.source_words ?? []).join(", ")}</Text>])}
      />
    </Stack>
  );
}

function SourcesView({ nav }: { nav: Nav }) {
  const theme = useHostTheme();
  const decisionRow = (d: Decision) => [
    <span key="id" style={{ fontFamily: MONO, fontSize: 12, whiteSpace: "nowrap", color: d.blocking ? theme.category.red : theme.text.primary }}>{d.decision_id}</span>,
    <Stack key="q" gap={2}>
      <Text size="small">{d.question}</Text>
      <Text size="small" tone="tertiary">{`${d.blocking ? "Blocking. " : ""}Assumed until answered: ${d.assumption}`}</Text>
    </Stack>,
    <Stack key="a" gap={2}>
      {(DECISION_REQS.get(d.decision_id) ?? []).map((id) => <ReqLink key={id} id={id} nav={nav} />)}
    </Stack>,
  ];
  return (
    <Stack gap={20}>
      <Stack gap={8}>
        <H2>Source precedence</H2>
        <Text tone="secondary">When sources disagree, the lower rank wins and the conflict is logged below.</Text>
        <Table
          headers={["Rank", "Key", "Source", "Used for"]}
          columnAlign={["center", "left", "left", "left"]}
          rows={G.sources.map((s) => [String(s.rank), <Mono key="k">{s.source}</Mono>, <Stack key="l" gap={2}><Link href={s.url}>{s.title}</Link><Text size="small" tone="tertiary">{s.date}</Text></Stack>, <Text key="u" size="small">{s.use}</Text>])}
        />
      </Stack>
      <Stack gap={8}>
        <H2>Open decisions</H2>
        <Text tone="secondary">Each carries the assumption the graph builds on. A blocking decision stops approval of every requirement that rests on it.</Text>
        <H3>From the sheet</H3>
        <Table headers={["ID", "Decision", "Rests on it"]} rows={G.decisions.filter((d) => d.origin === "sheet").map(decisionRow)} />
        <H3>Raised while building this graph</H3>
        <Table headers={["ID", "Decision", "Rests on it"]} rows={G.decisions.filter((d) => d.origin === "graph").map(decisionRow)} />
      </Stack>
      <Stack gap={8}>
        <H2>Conflicts resolved</H2>
        <Table headers={["ID", "Topic", "The graph follows", "Set aside"]} rows={G.conflicts.map((c) => [<Mono key="i" tone="tertiary">{c.conflict_id}</Mono>, <Text key="t" weight="medium">{c.topic}</Text>, c.keep, <Text key="d" size="small" tone="secondary">{c.drop}</Text>])} />
      </Stack>
      <Stack gap={8}>
        <H2>Inputs needed</H2>
        <Table headers={["ID", "Ask", "Origin"]} rows={G.inputs.map((i) => [<Mono key="i" tone="tertiary">{i.input_id}</Mono>, i.ask, <Text key="o" size="small" tone="tertiary">{i.origin}</Text>])} />
      </Stack>
    </Stack>
  );
}

/* ----------------------------------- Page ---------------------------------- */

const VIEWS: { id: View; label: string }[] = [
  { id: "requirements", label: "Requirements" },
  { id: "build", label: "Build order" },
  { id: "features", label: "Feature traceability" },
  { id: "data", label: "Data model" },
  { id: "catalogs", label: "Catalogs" },
  { id: "glossary", label: "Glossary" },
  { id: "sources", label: "Sources and decisions" },
];

export default function IrisRequirementsGraph() {
  const theme = useHostTheme();
  const [view, setView] = useCanvasState<View>("view", "requirements");
  const [phase, setPhase] = useCanvasState<PhaseFilter>("phase", "MVP");
  const [layer, setLayer] = useCanvasState<string>("layer", "product");
  const [moduleId, setModuleId] = useCanvasState<string>("module", "ORDERING");
  const [expanded, setExpanded] = useCanvasState<string | null>("expanded", null);
  const [entity, setEntity] = useCanvasState<string>("entity", "Shift");
  const [showChecks, setShowChecks] = useCanvasState<boolean>("showChecks", false);

  const nav: Nav = {
    req: (id) => {
      const r = REQ_BY_ID.get(id);
      if (!r) return;
      setView("requirements");
      if (!matchesPhase(r.phase, phase)) setPhase("ALL");
      setLayer(r.layer);
      setModuleId(r.module);
      setExpanded(id);
      setTimeout(() => document.getElementById(`req-${id}`)?.scrollIntoView({ behavior: "smooth", block: "start" }), 60);
    },
    entity: (name) => {
      const e = ENTITY_BY_NAME.get(name);
      if (!e) return;
      setView("data");
      if (!matchesPhase(e.phase, phase)) setPhase("ALL");
      setEntity(name);
    },
    view: (v) => setView(v),
  };

  const mvp = G.reqs.filter((r) => r.phase === "MVP");
  const traced = G.features.filter((f) => FEATURE_REQS.has(f.feature_id)).length;
  const approved = G.reqs.filter((r) => r.review === "approved").length;
  const blocking = G.decisions.filter((d) => d.blocking && d.status === "open").length;

  return (
    <Stack gap={18} style={{ padding: "8px 4px 32px 4px" }}>
      <Stack gap={6}>
        <H1>Iris requirements graph</H1>
        <Text tone="secondary">
          What Iris, Instawork's vendor management system for Compass agency labor, must do, as a dependency graph a software factory builds from. Each requirement has testable rules with their sources, the records it reads and writes, and what must be built before it.
        </Text>
        <Text size="small" tone="tertiary">{`Generated from the iris-requirements-graph repository (${G.meta.digest}). Edit the YAML there, not this canvas.`}</Text>
      </Stack>

      <Row gap={28} wrap>
        <Stat value={mvp.length} label="MVP requirements" />
        <Stat value={G.reqs.length} label="All requirements" />
        <Stat value={`${traced}/${G.features.length}`} label="Sheet features traced" tone={traced === G.features.length ? "success" : "danger"} />
        <Stat value={G.entities.length} label="Entities" />
        <Stat value={`${approved}/${G.reqs.length}`} label="Approved" tone={approved === G.reqs.length ? "success" : "warning"} />
        <Stat value={`${G.decisions.length} · ${blocking} blocking`} label="Open decisions" tone="warning" />
        <Stat value={`${G.meta.checks.length - FAILED.length}/${G.meta.checks.length}`} label="Validator checks pass" tone={FAILED.length ? "danger" : "success"} />
      </Row>

      {FAILED.length ? (
        <Callout tone="danger" title="Validator checks failing">
          <Stack gap={4}>
            {FAILED.flatMap((c) => c.problems.slice(0, 20).map((p, i) => <Text key={`${c.name}-${i}`} size="small">{`${c.name}: ${p}`}</Text>))}
          </Stack>
        </Callout>
      ) : null}

      <Row gap={6} wrap align="center">
        {VIEWS.map((v) => (
          <Pill key={v.id} active={view === v.id} onClick={() => setView(v.id)}>{v.label}</Pill>
        ))}
        <span style={{ flex: 1 }} />
        <Pill active={showChecks} onClick={() => setShowChecks(!showChecks)}>{showChecks ? "Hide validator checks" : "Show validator checks"}</Pill>
      </Row>

      {showChecks ? (
        <div style={{ border: `1px solid ${theme.stroke.tertiary}`, borderRadius: 8, padding: "10px 14px" }}>
          <Grid columns="minmax(0, 1fr) minmax(0, 1fr)" gap={4}>
            {G.meta.checks.map((c) => (
              <Row key={c.name} gap={10} align="start">
                <span style={{ fontFamily: MONO, fontSize: 12, minWidth: 40, color: c.problems.length ? theme.category.red : theme.category.green }}>{c.problems.length ? "FAIL" : "PASS"}</span>
                <Text size="small">{`${c.suite} · ${c.name.replace(/_/g, " ")}`}</Text>
              </Row>
            ))}
          </Grid>
        </div>
      ) : null}

      <Divider />

      {view === "requirements" ? <RequirementsView phase={phase} setPhase={setPhase} layer={layer} setLayer={setLayer} moduleId={moduleId} setModuleId={setModuleId} expanded={expanded} setExpanded={setExpanded} nav={nav} /> : null}
      {view === "build" ? <BuildView nav={nav} /> : null}
      {view === "features" ? <FeaturesView phase={phase} setPhase={setPhase} nav={nav} /> : null}
      {view === "data" ? <DataModelView phase={phase} setPhase={setPhase} entity={entity} nav={nav} /> : null}
      {view === "catalogs" ? <CatalogsView nav={nav} /> : null}
      {view === "glossary" ? <GlossaryView /> : null}
      {view === "sources" ? <SourcesView nav={nav} /> : null}
    </Stack>
  );
}
